class ParseError(Exception):
    def __init__(self, msg, code=255):
        super().__init__(msg)
        self.msg=msg
        self.code=code

class NamedColor:
    def __init__(self, name, idx):
        self.name=name
        self.idx=idx

class Ansi256:
    def __init__(self, n):
