        elif attr=="noitalic":
            style.italic=False
        elif attr=="underline":
            style.underline=True
        elif attr=="nounderline":
            style.underline=False
        elif attr=="intense":
            style.intense=True
        elif attr=="nointense":
            style.intense=False
        elif attr=="none":
