        elif arg=="--colors":
            if i+1>=len(argv):
                sys.stderr.write("option requires an argument: '--colors'\n")
                sys.exit(2)
            colors.append(argv[i+1])
            i+=2
            continue
        elif arg.startswith("--colors="):
            val=arg.split('=',1)[1]
            colors.append(val)
            i+=1
            continue
        elif arg=="--line-numbers":
            if i+1 < len(argv) and argv[i+1] in ("compact","aligned","fixed"):
                line_numbers=argv[i+1]
                i+=2
            else:
                line_numbers="compact"
                i+=1
            continue
        elif arg.startswith("--line-numbers="):
            sys.stderr.write(f"bad argument: '{arg}'\n")
            print_short_help_to_stderr()
            sys.exit(2)
        elif arg.startswith("--"):
            sys.stderr.write(f"bad argument: '{arg}'\n")
            print_short_help_to_stderr()
            sys.exit(2)
        elif arg.startswith("-") and len(arg)>1:
            sys.stderr.write(f"bad argument: '{arg}'\n")
            print_short_help_to_stderr()
            sys.exit(2)
        else:
            sys.stderr.write(f"bad argument: '{arg}'\n")
            print_short_help_to_stderr()
            sys.exit(2)
    return colors, line_numbers

def tokenize(s):
    tokens=[]
    i=0
    L=len(s)
    while i<L:
        c=s[i]
        if c.isalnum() or c=='_':
            j=i+1
            while j<L and (s[j].isalnum() or s[j]=='_'):
                j+=1
            tokens.append(s[i:j])
            i=j
        elif c.isspace():
            j=i+1
            while j<L and s[j].isspace():
                if s[j]=='\n' or s[j]=='\r':
                    break
                j+=1
            tokens.append(s[i:j])
            i=j
        else:
            tokens.append(c)
            i+=1
    return tokens

def lcs_indices(a,b):
    n=len(a); m=len(b)
    if n*m > 5000000:
        return [], []
    dp=[[0]*(m+1) for _ in range(n+1)]
    for i in range(n-1, -1, -1):
        ai=a[i]
        dpi=dp[i]
        dpi1=dp[i+1]
        for j in range(m-1, -1, -1):
            if ai==b[j]:
                dpi[j]=dpi1[j+1]+1
            else:
                if dpi1[j] > dpi[j+1]:
                    dpi[j]=dpi1[j]
                else:
                    dpi[j]=dpi[j+1]
    i=0; j=0
    ia=[]; ib=[]
    while i<n and j<m:
        if a[i]==b[j]:
            ia.append(i); ib.append(j)
            i+=1; j+=1
        else:
            if dp[i+1][j] > dp[i][j+1]:
                i+=1
            else:
                j+=1
    return ia, ib

def split_lines(tokens, common_set):
    lines=[]
    cur=[]
    cur_common=[]
    for idx, tok in enumerate(tokens):
        if tok=="\n":
            segs=[]
            cur_type=None
            cur_text=""
            for c_idx, c_tok in enumerate(cur):
                is_com = c_idx in set(cur_common)
                typ='COM' if is_com else 'REF'
                if cur_type is None:
                    cur_type=typ
                    cur_text=c_tok
                elif cur_type==typ:
                    cur_text+=c_tok
                else:
                    segs.append((cur_type, cur_text))
                    cur_type=typ
                    cur_text=c_tok
            if cur_text!="":
                segs.append((cur_type, cur_text))
            lines.append(segs)
            cur=[]
            cur_common=[]
        else:
            is_com = idx in common_set
            cur.append(tok)
            if is_com:
                cur_common.append(len(cur)-1)
    if cur:
        segs=[]
        cur_type=None
        cur_text=""
        for c_idx, c_tok in enumerate(cur):
            is_com = c_idx in set(cur_common)
            typ='COM' if is_com else 'REF'
            if cur_type is None:
                cur_type=typ
                cur_text=c_tok
            elif cur_type==typ:
                cur_text+=c_tok
            else:
                segs.append((cur_type, cur_text))
                cur_type=typ
                cur_text=c_tok
        if cur_text!="":
            segs.append((cur_type, cur_text))
        lines.append(segs)
    return lines

def parse_hunk_header(line):
    m=re.match(r'^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@', line)
    if not m:
        return None
    old_start=int(m.group(1))
    old_len=int(m.group(2)) if m.group(2) is not None else 1
    new_start=int(m.group(3))
    new_len=int(m.group(4)) if m.group(4) is not None else 1
    return old_start, old_len, new_start, new_len

def compute_line_number_widths(old_start, old_len, new_start, new_len, style):
    max_old = old_start + old_len -1 if old_len>0 else 0
    max_new = new_start + new_len -1 if new_len>0 else 0
    def digits(n):
        if n<=0:
            return 0
        return len(str(n))
    w_left = digits(max_old) if old_len>0 else 0
    w_right = digits(max_new) if new_len>0 else 0
    if style=="fixed":
        if old_len>0:
            w_left = max(3, w_left)
        if new_len>0:
            w_right = max(3, w_right)
    combined=0
    if w_left>0 and w_right>0:
        combined=w_left+1+w_right
    elif w_left>0:
        combined=w_left
    elif w_right>0:
        combined=w_right
    else:
        combined=0
    return w_left, w_right, combined

def format_line_numbers(old_line, new_line, w_left, w_right, combined, line_type):
    if line_type=='context':
        if w_left>0 and w_right>0:
            if old_line==new_line:
                return f"{old_line:>{combined}}"
            else:
                return f"{old_line:>{w_left}} {new_line:>{w_right}}"
        elif w_left>0:
            return f"{old_line:>{w_left}}"
        elif w_right>0:
            return f"{new_line:>{w_right}}"
        else:
            return ""
    elif line_type=='removed':
        if w_left>0 and w_right>0:
            return f"{old_line:>{w_left}}" + " "*(1+w_right)
        elif w_left>0:
            return f"{old_line:>{w_left}}"
        else:
            return ""
    elif line_type=='added':
        if w_left>0 and w_right>0:
            return " "*w_left + " " + f"{new_line:>{w_right}}"
        elif w_right>0:
            return f"{new_line:>{w_right}}"
        else:
            return ""
    else:
        return ""

