def print_version():
    sys.stderr.write("diffr 0.1.5\n")

def parse_args(argv):
    colors=[]
    line_numbers=None
    i=0
    while i < len(argv):
        arg=argv[i]
        if arg=="--help":
            print_long_help()
            sys.exit(0)
        elif arg=="-h":
            print_short_help()
            sys.exit(0)
        elif arg=="--version" or arg=="-V":
            print_version()
            sys.exit(0)
        elif arg=="--colors":
            if i+1>=len(argv):
                sys.stderr.write("option requires an argument: '--colors'\n")
                sys.exit(2)
            colors.append(argv[i+1])
            i+=2
            continue
        elif arg.startswith("--colors="):
            val=arg.split('=',1)[1]
            colors.append(val)
            i+=1
            continue
        elif arg=="--line-numbers":
            if i+1 < len(argv) and argv[i+1] in ("compact","aligned","fixed"):
                line_numbers=argv[i+1]
                i+=2
            else:
                line_numbers="compact"
                i+=1
            continue
        elif arg.startswith("--line-numbers="):
            sys.stderr.write(f"bad argument: '{arg}'\n")
            print_short_help_to_stderr()
            sys.exit(2)
        elif arg.startswith("--"):
            sys.stderr.write(f"bad argument: '{arg}'\n")
            print_short_help_to_stderr()
            sys.exit(2)
        elif arg.startswith("-") and len(arg)>1:
            sys.stderr.write(f"bad argument: '{arg}'\n")
            print_short_help_to_stderr()
            sys.exit(2)
        else:
            sys.stderr.write(f"bad argument: '{arg}'\n")
            print_short_help_to_stderr()
            sys.exit(2)
    return colors, line_numbers

def tokenize(s):
    tokens=[]
    i=0
    L=len(s)
    while i<L:
        c=s[i]
        if c.isalnum() or c=='_':
            j=i+1
            while j<L and (s[j].isalnum() or s[j]=='_'):
                j+=1
            tokens.append(s[i:j])
            i=j
        elif c.isspace():
            j=i+1
            while j<L and s[j].isspace():
                if s[j]=='\n' or s[j]=='\r':
                    break
                j+=1
            tokens.append(s[i:j])
            i=j
        else:
            tokens.append(c)
            i+=1
    return tokens

def extract_leading(s):
    i=0
    L=len(s)
    while i<L and s[i].isspace() and s[i] not in ('\n','\r'):
        i+=1
    return s[:i], s[i:]

def lcs_indices(a,b):
    n=len(a); m=len(b)
    if n*m > 5000000:
        return [], []
    dp=[[0]*(m+1) for _ in range(n+1)]
    for i in range(n-1, -1, -1):
        ai=a[i]
        dpi=dp[i]
        dpi1=dp[i+1]
        for j in range(m-1, -1, -1):
            if ai==b[j]:
                dpi[j]=dpi1[j+1]+1
            else:
                if dpi1[j] > dpi[j+1]:
                    dpi[j]=dpi1[j]
                else:
                    dpi[j]=dpi[j+1]
    i=0; j=0
    ia=[]; ib=[]
    while i<n and j<m:
        if a[i]==b[j]:
            ia.append(i); ib.append(j)
            i+=1; j+=1
        else:
            if dp[i+1][j] > dp[i][j+1]:
                i+=1
            else:
                j+=1
    return ia, ib

def split_lines(tokens, common_set):
    lines=[]
    cur=[]
    cur_common=[]
    for idx, tok in enumerate(tokens):
        if tok=="\n":
            segs=[]
            cur_type=None
            cur_text=""
            for c_idx, c_tok in enumerate(cur):
                is_com = c_idx in set(cur_common)
                typ='COM' if is_com else 'REF'
                if cur_type is None:
                    cur_type=typ
                    cur_text=c_tok
                elif cur_type==typ:
                    cur_text+=c_tok
                else:
                    segs.append((cur_type, cur_text))
                    cur_type=typ
                    cur_text=c_tok
            if cur_text!="":
                segs.append((cur_type, cur_text))
            lines.append(segs)
            cur=[]
            cur_common=[]
        else:
            is_com = idx in common_set
            cur.append(tok)
            if is_com:
                cur_common.append(len(cur)-1)
    if cur:
        segs=[]
        cur_type=None
        cur_text=""
        for c_idx, c_tok in enumerate(cur):
            is_com = c_idx in set(cur_common)
            typ='COM' if is_com else 'REF'
            if cur_type is None:
                cur_type=typ
                cur_text=c_tok
            elif cur_type==typ:
                cur_text+=c_tok
            else:
                segs.append((cur_type, cur_text))
                cur_type=typ
                cur_text=c_tok
        if cur_text!="":
            segs.append((cur_type, cur_text))
        lines.append(segs)
    return lines

def parse_hunk_header(line):
    m=re.match(r'^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@', line)
    if not m:
        return None
    old_start=int(m.group(1))
    old_len=int(m.group(2)) if m.group(2) is not None else 1
    new_start=int(m.group(3))
    new_len=int(m.group(4)) if m.group(4) is not None else 1
    return old_start, old_len, new_start, new_len

def compute_line_number_widths(old_start, old_len, new_start, new_len, style):
    max_old = old_start + old_len -1 if old_len>0 else 0
    max_new = new_start + new_len -1 if new_len>0 else 0
    def digits(n):
        if n<=0:
            return 0
        return len(str(n))
    d_old = digits(max_old) if old_len>0 else 0
    d_new = digits(max_new) if new_len>0 else 0
    max_digits = max(d_old, d_new)
    if style=="fixed":
        max_digits = max(3, max_digits)
        w_left = max_digits if old_len>0 else 0
        w_right = max_digits if new_len>0 else 0
    else:
        w_left = max_digits if old_len>0 else 0
        w_right = max_digits if new_len>0 else 0
    combined=0
    if w_left>0 and w_right>0:
        combined=w_left+1+w_right
    elif w_left>0:
        combined=w_left
    elif w_right>0:
        combined=w_right
    else:
        combined=0
    return w_left, w_right, combined

def format_line_numbers(old_line, new_line, w_left, w_right, combined, line_type):
    if line_type=='context':
        if w_left>0 and w_right>0:
            if old_line==new_line:
                return f"{old_line:>{combined}}"
            else:
                return f"{old_line:>{w_left}} {new_line:>{w_right}}"
        elif w_left>0:
            return f"{old_line:>{w_left}}"
        elif w_right>0:
            return f"{new_line:>{w_right}}"
        else:
            return ""
    elif line_type=='removed':
        if w_left>0 and w_right>0:
            return f"{old_line:>{w_left}}" + " "*(1+w_right)
        elif w_left>0:
            return f"{old_line:>{w_left}}"
        else:
            return ""
    elif line_type=='added':
        if w_left>0 and w_right>0:
            return " "*w_left + " " + f"{new_line:>{w_right}}"
        elif w_right>0:
            return f"{new_line:>{w_right}}"
        else:
            return ""
    else:
        return ""

def render_segments(segments, style_common, style_refine):
    # segments is list of (type, text) where type COM/REF
    # Returns string with ansi for each segment: \x1b[0m + style + text + \x1b[0m per segment
    out=""
    for typ, txt in segments:
        if txt=="":
            st = style_common.to_ansi() if typ=='COM' else style_refine.to_ansi()
            if st:
                out+=f"\x1b[0m{st}\x1b[0m"
            else:
                out+=f"\x1b[0m\x1b[0m"
            continue
        if typ=='COM':
            st=style_common.to_ansi()
            if st:
                out+=f"\x1b[0m{st}{txt}\x1b[0m"
            else:
                out+=f"\x1b[0m{txt}\x1b[0m"
        else:
            st=style_refine.to_ansi()
            if st:
                out+=f"\x1b[0m{st}{txt}\x1b[0m"
            else:
                out+=f"\x1b[0m{txt}\x1b[0m"
    return out

def main():
    colors_specs, line_numbers_style = parse_args(sys.argv[1:])
    styles=default_styles()
    for spec in colors_specs:
        try:
            face, actions = parse_colors_arg(spec)
        except ParseError as e:
            sys.stderr.write(e.msg)
            sys.exit(e.code)
        apply_actions(styles[face], actions)

    data = sys.stdin.read()
    if not data:
        return

    lines = data.splitlines(keepends=True)

    out_parts=[]
    in_hunk=False
    old_start=0; old_len=0; new_start=0; new_len=0
    old_line=0; new_line=0
    w_left=0; w_right=0; combined=0

    removed_buffer=[]
    added_buffer=[]

    def flush_buffers():
        nonlocal removed_buffer, added_buffer, out_parts, w_left, w_right, combined
        if not removed_buffer and not added_buffer:
            return
        if removed_buffer and added_buffer:
            rem_contents = [c for c,_,_ in removed_buffer]
            add_contents = [c for c,_,_ in added_buffer]

            rem_leadings=[]
            rem_rests=[]
            for c in rem_contents:
                lead, rest = extract_leading(c)
                rem_leadings.append(lead)
                rem_rests.append(rest)
            add_leadings=[]
            add_rests=[]
            for c in add_contents:
                lead, rest = extract_leading(c)
                add_leadings.append(lead)
                add_rests.append(rest)

            tok_rem=[]
            for idx, rest in enumerate(rem_rests):
                toks=tokenize(rest)
                tok_rem.extend(toks)
                if idx != len(rem_rests)-1:
                    tok_rem.append("\n")
            tok_add=[]
            for idx, rest in enumerate(add_rests):
                toks=tokenize(rest)
                tok_add.extend(toks)
                if idx != len(add_rests)-1:
                    tok_add.append("\n")

            ia, ib = lcs_indices(tok_rem, tok_add)
            lines_rem_rest = split_lines(tok_rem, set(ia))
            lines_add_rest = split_lines(tok_add, set(ib))

            # pad if needed for empty rests
            while len(lines_rem_rest) < len(rem_leadings):
                lines_rem_rest.append([])
            while len(lines_add_rest) < len(add_leadings):
                lines_add_rest.append([])

            lines_rem=[]
            for lead, rest_segs in zip(rem_leadings, lines_rem_rest):
                segs=[]
                if lead!="":
                    segs.append(('COM', lead))
                segs.extend(rest_segs)
                lines_rem.append(segs)
            lines_add=[]
            for lead, rest_segs in zip(add_leadings, lines_add_rest):
                segs=[]
                if lead!="":
                    segs.append(('COM', lead))
                segs.extend(rest_segs)
                lines_add.append(segs)

            for idx, (cont, old_num, raw) in enumerate(removed_buffer):
                segs = lines_rem[idx] if idx < len(lines_rem) else []
                if segs and segs[-1][0]=='REF':
                    segs.append(('COM',''))
                num_str=""
                if line_numbers_style:
                    num_str=format_line_numbers(old_num, None, w_left, w_right, combined, 'removed')
                part=""
                if line_numbers_style and num_str!="":
                    nstyle=styles['removed'].to_ansi()
                    if nstyle:
                        part+=f"\x1b[0m{nstyle}{num_str}\x1b[0m"
                    else:
                        part+=f"\x1b[0m{num_str}\x1b[0m"
                    if line_numbers_style=="aligned":
                        part+="\t"
                # prefix handling: if first seg is COM whitespace, merge prefix with it
                rstyle_ansi=styles['removed'].to_ansi()
                if segs and segs[0][0]=='COM' and segs[0][1]!="" and segs[0][1][0].isspace():
                    first_txt = segs[0][1]
                    merged = '-' + first_txt
                    if rstyle_ansi:
                        part+=f"\x1b[0m{rstyle_ansi}{merged}\x1b[0m"
                    else:
                        part+=f"\x1b[0m{merged}\x1b[0m"
                    remaining = segs[1:]
                else:
                    if rstyle_ansi:
                        part+=f"\x1b[0m{rstyle_ansi}-\x1b[0m"
                    else:
                        part+=f"\x1b[0m-\x1b[0m"
                    remaining = segs
                for typ, txt in remaining:
                    if txt=="":
                        st = styles['removed'].to_ansi() if typ=='COM' else styles['refine-removed'].to_ansi()
                        if st:
                            part+=f"\x1b[0m{st}\x1b[0m"
                        else:
                            part+=f"\x1b[0m\x1b[0m"
                        continue
                    if typ=='COM':
                        st=styles['removed'].to_ansi()
                        if st:
                            part+=f"\x1b[0m{st}{txt}\x1b[0m"
                        else:
                            part+=f"\x1b[0m{txt}\x1b[0m"
                    else:
                        st=styles['refine-removed'].to_ansi()
                        if st:
                            part+=f"\x1b[0m{st}{txt}\x1b[0m"
                        else:
                            part+=f"\x1b[0m{txt}\x1b[0m"
                part+="\n"
                out_parts.append(part)

            for idx, (cont, new_num, raw) in enumerate(added_buffer):
                segs = lines_add[idx] if idx < len(lines_add) else []
                if segs and segs[-1][0]=='REF':
                    segs.append(('COM',''))
                num_str=""
                if line_numbers_style:
                    num_str=format_line_numbers(None, new_num, w_left, w_right, combined, 'added')
                part=""
                if line_numbers_style and num_str!="":
                    nstyle=styles['added'].to_ansi()
                    if nstyle:
                        part+=f"\x1b[0m{nstyle}{num_str}\x1b[0m"
                    else:
                        part+=f"\x1b[0m{num_str}\x1b[0m"
                    if line_numbers_style=="aligned":
                        part+="\t"
                astyle_ansi=styles['added'].to_ansi()
                if segs and segs[0][0]=='COM' and segs[0][1]!="" and segs[0][1][0].isspace():
                    first_txt = segs[0][1]
                    merged = '+' + first_txt
                    if astyle_ansi:
                        part+=f"\x1b[0m{astyle_ansi}{merged}\x1b[0m"
                    else:
                        part+=f"\x1b[0m{merged}\x1b[0m"
                    remaining = segs[1:]
                else:
                    if astyle_ansi:
                        part+=f"\x1b[0m{astyle_ansi}+\x1b[0m"
                    else:
                        part+=f"\x1b[0m+\x1b[0m"
                    remaining = segs
                for typ, txt in remaining:
                    if txt=="":
                        st = styles['added'].to_ansi() if typ=='COM' else styles['refine-added'].to_ansi()
                        if st:
                            part+=f"\x1b[0m{st}\x1b[0m"
                        else:
                            part+=f"\x1b[0m\x1b[0m"
                        continue
                    if typ=='COM':
                        st=styles['added'].to_ansi()
                        if st:
                            part+=f"\x1b[0m{st}{txt}\x1b[0m"
                        else:
                            part+=f"\x1b[0m{txt}\x1b[0m"
                    else:
                        st=styles['refine-added'].to_ansi()
                        if st:
                            part+=f"\x1b[0m{st}{txt}\x1b[0m"
                        else:
                            part+=f"\x1b[0m{txt}\x1b[0m"
                part+="\n"
                out_parts.append(part)

        elif removed_buffer:
            for cont, old_num, raw in removed_buffer:
                # For only removed, treat leading as common? Our earlier logic for only removed had leading as common? In observed, leading spaces were common for only removed cases as well (e.g., "   foo" -> "-   " COM + REF). So we should apply same leading handling even for single side.
                lead, rest = extract_leading(cont)
                # rest fully refined
                num_str=""
                if line_numbers_style:
                    num_str=format_line_numbers(old_num, None, w_left, w_right, combined, 'removed')
                part=""
                if line_numbers_style and num_str!="":
                    nstyle=styles['removed'].to_ansi()
                    if nstyle:
                        part+=f"\x1b[0m{nstyle}{num_str}\x1b[0m"
                    else:
                        part+=f"\x1b[0m{num_str}\x1b[0m"
                    if line_numbers_style=="aligned":
                        part+="\t"
                rstyle_ansi=styles['removed'].to_ansi()
                # If lead present, merge
                if lead!="":
                    merged='-'+lead
                    if rstyle_ansi:
                        part+=f"\x1b[0m{rstyle_ansi}{merged}\x1b[0m"
                    else:
                        part+=f"\x1b[0m{merged}\x1b[0m"
                    if rest!="":
                        st=styles['refine-removed'].to_ansi()
                        if st:
                            part+=f"\x1b[0m{st}{rest}\x1b[0m"
                        else:
                            part+=f"\x1b[0m{rest}\x1b[0m"
                else:
                    if rstyle_ansi:
                        part+=f"\x1b[0m{rstyle_ansi}-\x1b[0m"
                    else:
                        part+=f"\x1b[0m-\x1b[0m"
                    if rest!="":
                        st=styles['refine-removed'].to_ansi()
                        if st:
                            part+=f"\x1b[0m{st}{rest}\x1b[0m"
                        else:
                            part+=f"\x1b[0m{rest}\x1b[0m"
                    elif cont=="" or lead=="":
                        # empty line after '-'
                        pass
                    else:
                        # cont only leading? Actually if cont == lead (only spaces), then we already output merged and no rest, that's fine
                        pass
                part+="\n"
                out_parts.append(part)

        elif added_buffer:
            for cont, new_num, raw in added_buffer:
                lead, rest = extract_leading(cont)
                num_str=""
                if line_numbers_style:
                    num_str=format_line_numbers(None, new_num, w_left, w_right, combined, 'added')
                part=""
                if line_numbers_style and num_str!="":
                    nstyle=styles['added'].to_ansi()
                    if nstyle:
                        part+=f"\x1b[0m{nstyle}{num_str}\x1b[0m"
                    else:
                        part+=f"\x1b[0m{num_str}\x1b[0m"
                    if line_numbers_style=="aligned":
                        part+="\t"
                astyle_ansi=styles['added'].to_ansi()
                if lead!="":
                    merged='+'+lead
                    if astyle_ansi:
                        part+=f"\x1b[0m{astyle_ansi}{merged}\x1b[0m"
                    else:
                        part+=f"\x1b[0m{merged}\x1b[0m"
                    if rest!="":
                        st=styles['refine-added'].to_ansi()
                        if st:
                            part+=f"\x1b[0m{st}{rest}\x1b[0m"
                        else:
                            part+=f"\x1b[0m{rest}\x1b[0m"
                else:
                    if astyle_ansi:
                        part+=f"\x1b[0m{astyle_ansi}+\x1b[0m"
                    else:
                        part+=f"\x1b[0m+\x1b[0m"
                    if rest!="":
                        st=styles['refine-added'].to_ansi()
                        if st:
                            part+=f"\x1b[0m{st}{rest}\x1b[0m"
                        else:
                            part+=f"\x1b[0m{rest}\x1b[0m"
                part+="\n"
                out_parts.append(part)

        removed_buffer.clear()
        added_buffer.clear()

    for raw_line in lines:
        line_nnl = raw_line.rstrip('\r\n')
        has_newline = raw_line.endswith('\n') or raw_line.endswith('\r\n')
        nl = "\n" if has_newline else ""
        if line_nnl.startswith('--- ') or line_nnl=='---':
            flush_buffers()
            in_hunk=False
            out_parts.append(f"\x1b[0m{line_nnl}\x1b[0m{nl}")
        elif line_nnl.startswith('+++ ') or line_nnl=='+++':
            flush_buffers()
            in_hunk=False
            out_parts.append(f"\x1b[0m{line_nnl}\x1b[0m{nl}")
        elif line_nnl.startswith('@@ '):
            flush_buffers()
            parsed=parse_hunk_header(line_nnl)
            if parsed:
                old_start, old_len, new_start, new_len = parsed
                old_line=old_start
                new_line=new_start
                if line_numbers_style:
                    w_left, w_right, combined = compute_line_number_widths(old_start, old_len, new_start, new_len, line_numbers_style)
                else:
                    w_left=w_right=combined=0
                in_hunk=True
            else:
                in_hunk=False
            out_parts.append(f"\x1b[0m{line_nnl}\x1b[0m{nl}")
        elif in_hunk and line_nnl.startswith(' '):
            flush_buffers()
            if line_numbers_style:
                num_str=format_line_numbers(old_line, new_line, w_left, w_right, combined, 'context')
                if line_numbers_style=="aligned":
                    part=f"{num_str}\t\x1b[0m{line_nnl}\x1b[0m{nl}"
                else:
                    part=f"{num_str}\x1b[0m{line_nnl}\x1b[0m{nl}"
