def tokenize(s):
    tokens=[]
    i=0
    L=len(s)
    while i<L:
        c=s[i]
        if c.isalnum() or c=='_':
            j=i+1
            while j<L and (s[j].isalnum() or s[j]=='_'):
                j+=1
            tokens.append(s[i:j])
            i=j
        elif c.isspace():
            j=i+1
            while j<L and s[j].isspace():
                if s[j]=='\n' or s[j]=='\r':
                    break
                j+=1
            tokens.append(s[i:j])
            i=j
        else:
            tokens.append(c)
            i+=1
    return tokens

