        return [], []
    dp=[[0]*(m+1) for _ in range(n+1)]
    for i in range(n-1, -1, -1):
        ai=a[i]
        dpi=dp[i]
        dpi1=dp[i+1]
        for j in range(m-1, -1, -1):
            if ai==b[j]:
                dpi[j]=dpi1[j+1]+1
            else:
                if dpi1[j] > dpi[j+1]:
                    dpi[j]=dpi1[j]
                else:
                    dpi[j]=dpi[j+1]
