            return True
        except:
            return False

def parse_0_255(s):
    s=s.strip()
    try:
        if s.lower().startswith('0x'):
            v=int(s,16)
        else:
            v=int(s)
    except:
        raise ParseError("not numeric")
    if v<0 or v>255:
        raise ParseError("out of range")
    return v

