    if s=="none":
        return None
    if s in NAMED:
        return NamedColor(s, NAMED[s])
    if ',' in s:
        parts=s.split(',')
        if len(parts)!=3:
            raise ParseError(f"unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{s}'\n")
        vals=[]
