NAMED = {
    "black":0,
    "red":1,
    "green":2,
    "yellow":3,
    "blue":4,
    "magenta":5,
    "cyan":6,
    "white":7,
}

class ParseError(Exception):
    def __init__(self, msg, code=255):
        super().__init__(msg)
        self.msg=msg
        self.code=code

class NamedColor:
    def __init__(self, name, idx):
        self.name=name
        self.idx=idx
class Ansi256:
    def __init__(self, n):
        self.n=n
class RGB:
    def __init__(self,r,g,b):
        self.r=r; self.g=g; self.b=b

def is_numeric_token(s):
    if not s:
        return False
    s=s.strip()
    if s.lower().startswith('0x'):
        if len(s)<=2:
            return False
        try:
            int(s,16)
            return True
        except:
            return False
    else:
        try:
            int(s)
            return True
        except:
            return False

def parse_0_255(s):
    s=s.strip()
    try:
        if s.lower().startswith('0x'):
            v=int(s,16)
        else:
            v=int(s)
    except:
        raise ParseError("not numeric")
    if v<0 or v>255:
        raise ParseError("out of range")
    return v

def parse_color_value(s):
    if s=="none":
        return None
    if s in NAMED:
        return NamedColor(s, NAMED[s])
    if ',' in s:
        parts=s.split(',')
        if len(parts)!=3:
            raise ParseError(f"unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{s}'\n")
        vals=[]
        for p in parts:
            if p=="":
                raise ParseError(f"unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{s}'\n")
            try:
                vals.append(parse_0_255(p))
            except ParseError:
                raise ParseError(f"unexpected color value: unrecognized RGB color triple, should be '[0-255],[0-255],[0-255]' (or a hex triple), but is '{s}'\n")
        return RGB(vals[0], vals[1], vals[2])
    else:
        if is_numeric_token(s):
            try:
                v=parse_0_255(s)
                return Ansi256(v)
            except ParseError:
                raise ParseError(f"unexpected color value: unrecognized ansi256 color number, should be '[0-255]' (or a hex number), but is '{s}'\n")
        else:
            raise ParseError(f"unexpected color value: unrecognized color name '{s}'. Choose from: black, blue, green, red, cyan, magenta, yellow, white\n")

class Style:
    __slots__ = ('fg','bg','bold','dimmed','italic','underline','intense')
    def __init__(self, fg=None, bg=None, bold=False, dimmed=False, italic=False, underline=False, intense=False):
        self.fg=fg
        self.bg=bg
        self.bold=bold
        self.dimmed=dimmed
        self.italic=italic
        self.underline=underline
        self.intense=intense
    def clear(self):
        self.fg=None
        self.bg=None
        self.bold=False
        self.dimmed=False
        self.italic=False
        self.underline=False
        self.intense=False
    def to_ansi(self):
        codes=[]
        if self.bold:
            codes.append("1")
        if self.dimmed:
            codes.append("2")
        if self.italic:
            codes.append("3")
        if self.underline:
            codes.append("4")
        if self.fg is not None:
            if isinstance(self.fg, NamedColor):
                if self.intense:
                    codes.append(f"38;5;{self.fg.idx+8}")
                else:
                    codes.append(str(30+self.fg.idx))
            elif isinstance(self.fg, Ansi256):
                codes.append(f"38;5;{self.fg.n}")
            elif isinstance(self.fg, RGB):
                codes.append(f"38;2;{self.fg.r};{self.fg.g};{self.fg.b}")
        if self.bg is not None:
            if isinstance(self.bg, NamedColor):
                if self.intense:
                    codes.append(f"48;5;{self.bg.idx+8}")
                else:
                    codes.append(str(40+self.bg.idx))
            elif isinstance(self.bg, Ansi256):
                codes.append(f"48;5;{self.bg.n}")
            elif isinstance(self.bg, RGB):
                codes.append(f"48;2;{self.bg.r};{self.bg.g};{self.bg.b}")
        if not codes:
            return ""
        return "".join(f"\x1b[{c}m" for c in codes)

def default_styles():
    styles={}
    styles['added']=Style(fg=NamedColor("green", NAMED["green"]))
    styles['removed']=Style(fg=NamedColor("red", NAMED["red"]))
    styles['refine-added']=Style(fg=RGB(255,255,255), bg=NamedColor("green", NAMED["green"]), bold=True)
    styles['refine-removed']=Style(fg=RGB(255,255,255), bg=NamedColor("red", NAMED["red"]), bold=True)
    return styles

def parse_colors_arg(spec):
    if not spec:
        raise ParseError(f"unexpected face name: got '', expected added|refine-added|removed|refine-removed\n")
    tokens=spec.split(':')
    face=tokens[0]
    if face not in ('added','removed','refine-added','refine-removed'):
        raise ParseError(f"unexpected face name: got '{face}', expected added|refine-added|removed|refine-removed\n")
    actions=[]
    i=1
    while i < len(tokens):
        attr=tokens[i]
        if attr=="":
            raise ParseError(f"unexpected attribute name: got '', expected foreground|background|italic|noitalic|bold|nobold|dimmed|nodimmed|intense|nointense|underline|nounderline|none\n")
        if attr=="foreground" or attr=="background":
            if i+1>=len(tokens):
                raise ParseError(f"error parsing color: missing color value for face '{face}'\n")
            color_str=tokens[i+1]
            if color_str=="":
                raise ParseError(f"unexpected attribute name: got '', expected foreground|background|italic|noitalic|bold|nobold|dimmed|nodimmed|intense|nointense|underline|nounderline|none\n")
            try:
                col=parse_color_value(color_str)
            except ParseError as e:
                raise e
            actions.append((attr, col))
            i+=2
        else:
            base_flags=("italic","bold","dimmed","intense","underline")
            if attr=="none":
                actions.append((attr, None))
                i+=1
            elif attr in base_flags or (attr.startswith("no") and attr[2:] in base_flags):
                actions.append((attr, None))
                i+=1
            else:
                raise ParseError(f"unexpected attribute name: got '{attr}', expected foreground|background|italic|noitalic|bold|nobold|dimmed|nodimmed|intense|nointense|underline|nounderline|none\n")
    return face, actions

def apply_actions(style, actions):
    for attr, val in actions:
        if attr=="foreground":
            style.fg=val
        elif attr=="background":
            style.bg=val
        elif attr=="bold":
            style.bold=True
        elif attr=="nobold":
            style.bold=False
        elif attr=="dimmed":
            style.dimmed=True
        elif attr=="nodimmed":
            style.dimmed=False
        elif attr=="italic":
            style.italic=True
        elif attr=="noitalic":
            style.italic=False
        elif attr=="underline":
            style.underline=True
        elif attr=="nounderline":
            style.underline=False
        elif attr=="intense":
            style.intense=True
        elif attr=="nointense":
            style.intense=False
        elif attr=="none":
            style.clear()

